{"command": "cd /tmp/sv-fa6fae48299b4d01b1d53bc9e5eec020/advanced-multi-complexity && python3 -c "
import json
with open('after-cpm-packages.json') as f:
    data = json.load(f)
with open('baseline-packages.json') as f:
    base = json.load(f)

# Build lookup: project_name -> framework -> package -> version
def build_map(d):
    m = {}
    for p in d['projects']:
        name = p['path'].split('/')[-1]
        for fw in p['frameworks']:
            for pkg in fw['topLevelPackages']:
                key = (name, fw['framework'], pkg['id'])
                m[key] = pkg['resolvedVersion']
    return m

bm = build_map(base)
am = build_map(data)

changes = []
unchanged = []
for key in sorted(set(list(bm.keys()) + list(am.keys()))):
    bv = bm.get(key, 'N/A')
    av = am.get(key, 'N/A')
    if bv != av:
        changes.append((key, bv, av))
    else:
        unchanged.append(key)

print('=== CHANGES ===')
for (proj, fw, pkg), bv, av in changes:
    print(f'{proj} [{fw}] {pkg}: {bv} -> {av}')
print(f'\n=== UNCHANGED: {len(unchanged)} packages ===')
"", "description": "Compare baseline vs after packages"}
